import { getLogFunction } from '../../../exported-utils/logger';
import { createElement, updateDynamicText, updateDynamicAttribute, updateDynamicProperty, updateConditionalElements, replace, dynamicText, useElementIfElse } from '../shared/dom-manipulation';
import { translate } from '@ps-refarch-ux/mfe-utils';
import { stringHasCharacters } from '../shared/string-utils';
import { runValidationEngine } from './validation-engine/validate-engine';
import { LabeledWidget } from './labeled-widget';
const log = getLogFunction('input-widgets', 'neon-abstract-input-field');
export class AbstractInputField extends LabeledWidget {
    static get observedAttributes() {
        return super.observedAttributes.concat([
            'data-is-read-only',
            'value',
            'data-is-required',
            'disabled',
            'data-size',
            'data-success-message',
            'data-constrain-description'
        ]);
    }
    static get inputProperties() {
        return [
            'modelValue'
        ];
    }
    get customValidationFunction() {
        return this.customValidate;
    }
    set customValidationFunction(value) {
        this.customValidate = value;
        this.generateValidationRules();
    }
    get isReadOnly() {
        return this.getAttribute('data-is-read-only') === 'true';
    }
    get value() {
        const result = this.inputSelector();
        if (result != null) {
            log(`get value() called - value: ${result.value}`);
            return result.value;
        }
        log('get value() called - inputSelector not there yet');
    }
    set value(value) {
        log(`set value(${value}) called`);
        this.setValue(value);
        this.setReadonlyText();
    }
    get modelValue() {
        const result = this.inputSelector();
        if (result != null) {
            log(`get modelValue() called - value: ${result.modelValue}`);
            //In the Angular 2+ event listener, we grab event.target.modelValue
            return result.modelValue;
        }
        log('get modelValue() called - inputSelector not there yet');
    }
    set modelValue(value) {
        log(`set modelValue(${value})`);
        //If the value isn't what is expected for this type, then it will return undefined.
        value = this.validateModelValueType(value);
        const modelValueChanged = this.setModelValue(value);
        if (modelValueChanged) {
            //only show the validation message IF an error message is already showing.
            const showValidationResult = !this.errorElement.classList.contains('neon-sr-only');
            this.validateWidget(showValidationResult);
        }
        this.setReadonlyText();
    }
    constructor() {
        super();
        this.isIdRequired = true;
        this.validators = [];
        this.isValid = true;
        this.errorPresentWhenBlurOccurred = false;
        this.isIdRequired = true;
        this.inputElement = this.renderInputElement();
        this.errorElement = createElement('p', {
            attrs: {
                class: 'neon-error-message neon-sr-only',
                'aria-live': 'assertive',
                'aria-relevant': 'additions removals',
            }
        });
        this.readOnlyElement = createElement('p', {
            attrs: { class: 'neon-abstract-input-field-readonly-text' },
            text: dynamicText(() => { return this.getReadOnlyText() || ''; })
        });
        this.successElement = createElement('p', {
            attrs: {
                class: 'neon-success-message',
                'aria-live': 'assertive',
                'aria-relevant': 'additions removals',
            }
        });
    }
    connectedCallback() {
        super.connectedCallback();
        //This attribute isn't used for styling, it's
        //for the validation utils to pick it up.
        this.setAttribute('neon-2_20_1-input-field', '');
    }
    getReadOnlyText() {
        return this.inputElement.value;
    }
    setDataSuccessMessage() {
        if ((this.getAttribute('data-success-message') || '').length > 0) {
            this.successElement.textContent = this.getAttribute('data-success-message');
            this.successElement.classList.remove('neon-sr-only');
        }
        else {
            this.successElement.textContent = '';
            this.successElement.classList.add('neon-sr-only');
        }
    }
    //Note that the input element could potentially be a Select element, or a radio group or something.
    inputSelector() {
        return this.inputElement;
    }
    setReadonlyText() {
        updateDynamicText(this);
    }
    getBadgeText() {
        if (this.getAttribute('data-is-required') !== 'true' && this.getAttribute('data-show-optional-badge') === 'true') {
            return translate('neon|input fields|optional');
        }
        else {
            return translate('neon|input fields|required');
        }
    }
    isShowBadge() {
        const showOptionalBadge = this.getAttribute('data-show-optional-badge') === 'true';
        const isRequired = this.getAttribute('data-is-required') === 'true';
        if (isRequired) {
            return this.getAttribute('data-hide-required-badge') !== 'true' || (!this.isValid && this.invalidRule === 'isRequired');
        }
        else if (showOptionalBadge) {
            return true;
        }
        return false;
    }
    render() {
        log('render function called');
        return super.render().concat(this.errorElement).concat(this.successElement);
    }
    renderContent() {
        return useElementIfElse(() => { return this.getAttribute('data-is-read-only') === 'true'; }, () => { return this.readOnlyElement; }, () => { return this.inputElement; });
    }
    inputChange() {
        log('inputChange() called');
        this.validateWidget();
        this.setValue(this.value);
        this.dispatchEvent(new Event('modelValueChange', { bubbles: true }));
    }
    clearInputField() {
        //Clear the boolean that will make errors show up while typing
        this.errorPresentWhenBlurOccurred = false;
        //Clear the modelValue
        this.setModelValue(undefined);
        //Run validation on the new value
        //Let things outside the widget know that things changed
        this.inputChange();
    }
    resetValidation() {
        //Clear the boolean that will make errors show up while typing
        this.errorPresentWhenBlurOccurred = false;
        this.validateWidget(false, false);
        //validateWidget will always show the badge if the widget is invalid,
        //therefore we need to clear it here
        if (this.highlightBadge) {
            this.highlightBadge = false;
            updateConditionalElements(this);
            updateDynamicAttribute(this, 'class');
        }
    }
    /**
     * When the user enters data into this field and the focus is lost, the widget calls this function on blur and fires
     * a focus event. We check if there is an error message, if there is an error message,
     * then we start allowing the error messages to be shown
     */
    focusLost(event) {
        log('focus lost');
        if (this.blurInterceptor != null) {
            this.blurInterceptor(this);
        }
        this.validateWidget(true, true);
        this.dispatchEvent(new Event('blur'));
    }
    /**
     *
     * @param showValidationResult
     * @param fromBlur
     * @param showValidationResultOnRequired Defaults to true. You can set this to false to prevent
     * the badge from getting highlighted if the field fails isRequired.  We needed this specifically when
     * changing steps with the stepper component.
     * @returns {boolean} - True means the widget is valid. False means the widget is invalid.
     */
    validateWidget(showValidationResult, fromBlur, showValidationResultOnRequired) {
        const previousHighlightBadge = this.highlightBadge;
        //default fromBlur to false.
        if (fromBlur == null) {
            fromBlur = false;
        }
        const validationResult = this.runValidationEngine();
        this.isValid = validationResult.isValid;
        this.highlightBadge = false; //default to false, and then flip it on if it's required and there is no data.
        if (this.isValid) {
            this.setError('');
            this.invalidRule = '';
            updateConditionalElements(this);
            updateDynamicAttribute(this, 'class');
        }
        else {
            this.invalidRule = validationResult.invalidRule;
            if (validationResult.invalidRule === 'isRequired') {
                this.setError('');
                if (showValidationResultOnRequired !== false) {
                    //NOTE: Normal operation is that even if "showValidationResult === false" we STILL elevate the badge.
                    //This is per Arleigh Morgan.
                    //When using the stepper component though, we use validateFields2 which has the ability to turn this part off.
                    this.highlightBadge = true;
                }
            }
            else {
                //Just because the input field is invalid and there is a non-is-required error message does not mean we are going to show it.
                //We only show it after blur or if the function call forces it.
                if (fromBlur && !this.errorPresentWhenBlurOccurred) {
                    //This flag should only get set when this is called through the focusLost function.
                    this.errorPresentWhenBlurOccurred = true;
                }
                if (showValidationResult || (showValidationResult == null && this.errorPresentWhenBlurOccurred)) {
                    this.setError(validationResult.errorMessage || '');
                }
                else {
                    this.setError('');
                }
            }
        }
        if (previousHighlightBadge !== this.highlightBadge) {
            updateConditionalElements(this);
            updateDynamicAttribute(this, 'class');
        }
        return this.isValid;
    }
    runValidationEngine() {
        return runValidationEngine(this.value, this.validators);
    }
    getSizeClass() {
        const size = this.getAttribute('data-size');
        switch (size) {
            case 'small':
                return ' input-size-small';
            case 'medium':
                return ' input-size-medium';
            case 'large':
                return ' input-size-large';
            case 'x-large':
                return ' input-size-x-large';
            case 'auto':
                return ' input-size-auto';
            default:
                return '';
        }
    }
    setError(value) {
        //Toggle the sr-only class depending on if there is an error message being set or not.
        if (value != null && value.trim().length > 0) {
            this.errorElement.textContent = value;
            this.errorElement.classList.remove('neon-sr-only');
            this.successElement.textContent = '';
            this.successElement.classList.add('neon-sr-only');
        }
        else {
            this.errorElement.textContent = '';
            this.errorElement.classList.add('neon-sr-only');
            this.setDataSuccessMessage();
        }
    }
    redrawInput() {
        if (this.getAttribute('data-is-read-only') === 'true') {
            //When readonly becomes true, we need to put the readonly div into the DOM, but only if it isn't there already.
            this.readOnlyElement.textContent = this.getReadOnlyText() || '';
            if (!this.readOnlyElement.isConnected) {
                replace(this.readOnlyElement, this.inputElement);
            }
        }
        else {
            //When readonly becomes false, if the readonly div is already in the DOM, we need to replace it with the input field.
            if (!this.inputElement.isConnected) {
                replace(this.inputElement, this.readOnlyElement);
            }
        }
    }
    /**
     * Checks to be sure that any required attributes are present, otherwise an error gets logged.
     */
    validateInputs() {
        super.validateInputs();
        if (!stringHasCharacters(this.getAttribute('data-label-text'))) {
            console.error('The attribute data-label-text is required for the following element: ');
            console.log(this);
        }
    }
    attributeChanged(attribute, oldValue, newValue) {
        // attributeChanged is called when attributes listed in "static get observedAttributes()" are changed.
        log('attribute changed ' + attribute + ': ' + newValue);
        super.attributeChanged(attribute, oldValue, newValue);
        switch (attribute) {
            case 'value':
                this.setValue(newValue);
                break;
            case 'data-label-text':
                updateDynamicText(this);
                break;
            case 'data-show-label':
                updateConditionalElements(this);
                break;
            case 'data-helper-text':
                updateConditionalElements(this);
                updateDynamicText(this);
                break;
            case 'data-tooltip-text':
                updateConditionalElements(this);
                this.tooltipTextNode.nodeValue = newValue;
                break;
            case 'id':
                updateDynamicAttribute(this, 'id');
                updateDynamicAttribute(this, 'for');
                updateDynamicAttribute(this, 'data-target-id');
                break;
            case 'data-is-required':
                updateConditionalElements(this);
                updateDynamicText(this);
                break;
            case 'disabled':
                updateDynamicProperty(this, 'disabled');
                break;
            case 'data-is-read-only':
                this.redrawInput();
                break;
            case 'data-show-optional-badge':
                updateConditionalElements(this);
                updateDynamicText(this);
                break;
            case 'data-hide-required-badge':
                updateConditionalElements(this);
                break;
            case 'data-size':
                updateDynamicAttribute(this, 'class');
                break;
            case 'data-success-message':
                this.setDataSuccessMessage();
                break;
            case 'data-constrain-description':
                updateDynamicAttribute(this, 'class');
                break;
        }
        this.generateValidationRules();
    }
    getDisabledStatus() {
        const disabledAttr = this.getAttribute('disabled');
        return disabledAttr != null && disabledAttr !== 'false';
    }
    addCustomValidateToValidators() {
        if (this.customValidationFunction != null) {
            this.validators.push({
                execute: this.customValidationFunction,
                condition: {
                    element: this
                }
            });
        }
    }
}
